-- ─────────────────────────────────────────────────────────────────────────
-- The two percentages of a version's plan as Primavera P6 defines them
-- (owner's decision of 2026-10-26, replacing the definition of 091):
--
--   cost_complete_pct  Cost % Complete       = act_cost / total_cost  × 100
--   act_pct_spent      (*)Cost % of Budget   = act_cost / target_cost × 100
--
-- Each is empty while its two sides are not both given, or its divisor is
-- not above zero — never a figure nobody gave. Both stay generated by the
-- database: nobody types them.
-- ─────────────────────────────────────────────────────────────────────────

ALTER TABLE activity_plan DROP COLUMN cost_complete_pct;
ALTER TABLE activity_plan DROP COLUMN act_pct_spent;
ALTER TABLE activity_plan ADD COLUMN cost_complete_pct numeric(14,4)
  GENERATED ALWAYS AS (CASE WHEN total_cost > 0 THEN round(act_cost / total_cost * 100, 4) END) STORED;
ALTER TABLE activity_plan ADD COLUMN act_pct_spent numeric(14,4)
  GENERATED ALWAYS AS (CASE WHEN target_cost > 0 THEN round(act_cost / target_cost * 100, 4) END) STORED;
